const trips=[{name:'Shimla & Kufri',meta:'3 days / 2 nights · Starts from Shimla',days:['Arrive in Shimla. Settle in and explore Mall Road and the Ridge at your own pace.','Explore Kufri and the surrounding hills, with time for views and local stops.','Enjoy a relaxed morning before your onward departure.']},{name:'Shimla to Manali',meta:'6 days / 5 nights · Starts from Shimla',days:['Arrive in Shimla and enjoy an easy evening around the Ridge.','Discover Kufri and Shimla’s hill-town sights.','Travel towards Manali through the Kullu Valley, with scenic stops en route.','Explore Manali, including Old Manali and local landmarks.','Plan a Solang Valley excursion, subject to conditions and access.','Depart with a final morning in the mountains.']},{name:'Kinnaur & Spiti Valley',meta:'8 days / 7 nights · Starts from Shimla · Seasonal mountain route',days:['Travel from Shimla towards the Sangla Valley.','Explore Sangla and Chitkul, subject to road access.','Continue to Kalpa for views of the Kinnaur Kailash range.','Journey towards Tabo via Nako, allowing time to adapt to altitude.','Travel to Kaza and explore the valley at a gentle pace.','Visit nearby villages and monasteries as conditions allow.','Begin the return journey towards Kinnaur.','Return to Shimla.']}];
const dialog=document.querySelector('#trip-dialog');document.querySelectorAll('[data-trip]').forEach(b=>b.addEventListener('click',()=>{const t=trips[Number(b.dataset.trip)];document.querySelector('#dialog-title').textContent=t.name;document.querySelector('#dialog-meta').textContent=t.meta;document.querySelector('#dialog-days').replaceChildren(...t.days.map((day,i)=>{const li=document.createElement('li');li.textContent=`Day ${i+1}: ${day}`;return li}));document.querySelector('[name="trip"]').value=t.name;dialog.showModal()}));document.querySelector('.dialog-close').onclick=()=>dialog.close();document.querySelector('#dialog-enquire').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.querySelectorAll('.package').forEach(c=>c.hidden=b.dataset.filter!=='all'&&c.dataset.category!==b.dataset.filter)}));document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.classList.contains('active'))));const date=document.querySelector('[name="date"]');const now=new Date();date.min=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;document.querySelector('#enquiry').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);document.querySelector('#enquiry-text').value=`Hello Aapki Yatra! I’m ${d.get('name')}. I’d like to enquire about ${d.get('trip')} from Shimla.\nTravel date: ${d.get('date')}\nTravellers: ${d.get('people')}\n${d.get('notes')||''}\nPlease share a personalised itinerary, inclusions and quote.`;document.querySelector('#enquiry-result').hidden=false;document.querySelector('#form-status').textContent='Your enquiry is ready. Copy it and send it through one of our social channels. It has not been sent yet.'});document.querySelector('#copy').onclick=async()=>{const t=document.querySelector('#enquiry-text');try{await navigator.clipboard.writeText(t.value);document.querySelector('#form-status').textContent='Enquiry copied. Open Instagram or Facebook and paste it into a message.'}catch{t.focus();t.select();document.querySelector('#form-status').textContent='Select and copy the enquiry below, then paste it into a message.'}};document.querySelector('#year').textContent=new Date().getFullYear();
const banners=[{name:'HIMACHAL',image:'hero.jpg'},{name:'MANALI',image:'mountains.jpg'},{name:'SPITI VALLEY',image:'valley.jpg'}];let bannerIndex=0;function setBanner(index){bannerIndex=(index+banners.length)%banners.length;const b=banners[bannerIndex];document.querySelector('#hero-destination').textContent=b.name;document.querySelector('.hero').style.backgroundImage=`linear-gradient(90deg,#053d75aa,#17673525),url('assets/${b.image}')`;document.querySelectorAll('[data-slide]').forEach(x=>{x.classList.toggle('selected',Number(x.dataset.slide)===bannerIndex);x.setAttribute('aria-pressed',String(Number(x.dataset.slide)===bannerIndex))})}document.querySelector('#hero-prev').onclick=()=>setBanner(bannerIndex-1);document.querySelector('#hero-next').onclick=()=>setBanner(bannerIndex+1);document.querySelectorAll('[data-slide]').forEach(x=>x.onclick=()=>setBanner(Number(x.dataset.slide)));document.querySelector('#explore-destination').onclick=()=>document.querySelector(`[data-trip="${document.querySelector('#destination').value}"]`).click();setBanner(0);
